func TestClubRecord(t *testing.T) {
	tests := []struct {
		name string
		club Club
		want []string
	}{
		{
			name: "full club",
			club: Club{
				ClubID:       "SCCP",
				Name:         "Sport Club Corinthians Paulista",
				Championship: "SERIE A",
				FoundingDate: "1910-09-01",
