			},
			want: []string{
				"SCCP", "Sport Club Corinthians Paulista", "SERIE A", "1910-09-01",
				"São Paulo", "SP", "Brasil", "Neo Química Arena", "Augusto Melo",
				"Timão", "preto|branco",
			},
