			club: Club{ClubID: "AAA", Name: "Club A", Championship: "SERIE A", FoundingDate: "01/09/1910"},
			want: []string{"AAA", "Club A", "SERIE A", "", "", "", "", "", "", "", ""},
		},
		{
			name: "every optional absent",
			club: Club{ClubID: "AAA", Championship: "SERIE B"},
