			}
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("Record() = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestPlayerRecord(t *testing.T) {
	tests := []struct {
		name   string
		clubID string
		player Player
		want   []string
	}{
		{
			name:   "full player",
			clubID: "SCCP",
			player: Player{
				PlayerID:    "SCCP-10",
				Name:        "Rodrigo Garro",
				Age:         ptr(26),
				Goals:       ptr(8),
