				ShirtNumber: ptr(1),
			},
			want: []string{"SCCP", "SCCP-1", "Hugo Souza", "25", "0", "2024-07-20", "Goleiro", "1"},
		},
		{
			name:   "absent numbers are empty, not zero",
			clubID: "AAA",
			player: Player{PlayerID: "P1", Name: "Player One"},
			want:   []string{"AAA", "P1", "Player One", "", "", "", "", ""},
