	// NAC is filtered out and AVA has no players: neither is an error.
	checkLog(t, logw.String(), nil)

	if got, want := strings.Count(clubs.String(), "\r\n")-1, 5; got != want {
		t.Errorf("clubs.csv has %d rows, want %d", got, want)
